        colAllCurrentUserRoles,
        Filter(
            colCurrentUserRoles,
            StartsWith(
                Name,
                "VSB"
            )
        ),
        Filter(
            colCurrentUserTeamsRoles,
            StartsWith(
                Name,
                "VSB"
            )
        )
    );
    ClearCollect(
        colDistinctCurrentUserTeamsRoles,
        ForAll(
            Distinct(
                colAllCurrentUserRoles,
                ThisRecord
